import{_ as t,o,c as d,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ioBroker : attribution automatique des rôles","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/mqtt-client/iobroker-roles.md","filePath":"fr/projects/mqtt-client/iobroker-roles.md","lastUpdated":1794046966000}'),a={name:"fr/projects/mqtt-client/iobroker-roles.md"};function r(c,e,i,n,l,u){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="iobroker-role-mapping" tabindex="-1">ioBroker : attribution automatique des rôles <a class="header-anchor" href="#iobroker-role-mapping" aria-label="Permalink to &quot;ioBroker : attribution automatique des rôles {#iobroker-role-mapping}&quot;">​</a></h1><p>Le JavaScript optionnel est fourni avec MQTT-Client <strong>0.1.26</strong> et s’exécute dans l’adaptateur JavaScript d’ioBroker. Il exploite les métadonnées transmises <code>device_class</code> et <code>unit_of_measurement</code>. Seuls les cas non ambigus sont traités ; les valeurs MQTT, types, unités, identifiants de connexion et canaux de commande ne sont pas réécrits.</p><h2 id="setup-0126" tabindex="-1">Nouveauté 0.1.26 : création automatique de la base <a class="header-anchor" href="#setup-0126" aria-label="Permalink to &quot;Nouveauté 0.1.26 : création automatique de la base {#setup-0126}&quot;">​</a></h2><p>Les dossiers de base du script (<code>virtualRoot</code>, <code>aliasRoot</code>) et les deux points de sauvegarde (<code>virtualBackupId</code>, <code>backupId</code>) absents sont désormais créés automatiquement au démarrage dans <strong>tous les modes</strong>, y compris <code>preview</code> et <code>restore</code>. Les dossiers, sauvegardes, valeurs et rôles manuels existants ne sont pas écrasés. Les nouveaux journaux contiennent des structures vides valides. Autorisez <code>setObject</code> dans l’instance JavaScript même pour l’aperçu. Les autorisations manquantes et les chemins incompatibles sont signalés comme erreurs. L’aperçu ne crée aucun point VIS 2 commandable et ne modifie ni les rôles MQTT ni les valeurs des appareils ; utilisez <code>mode: &#39;apply&#39;</code> après vérification pour ces opérations. Le traitement événementiel de la version 0.1.25 est conservé.</p><h2 id="fix-0125" tabindex="-1">Correction 0.1.25 : objets absents sans avertissements <a class="header-anchor" href="#fix-0125" aria-label="Permalink to &quot;Correction 0.1.25 : objets absents sans avertissements {#fix-0125}&quot;">​</a></h2><p>L’adaptateur JavaScript <strong>10.4.10</strong> émet aussi un avertissement lorsque <code>getObject</code> lit un identifiant absent. Le script vérifie désormais <code>existsObject</code> et <code>existsState</code> avant toute lecture d’objet ou d’état : journal, métadonnées optionnelles, dossiers et points virtuels non encore créés. La protection précédente utilisant seulement <code>getObject</code> était insuffisante.</p><p>L’aperçu affiche des lignes <code>Preview VIS 2</code> mais crée uniquement les dossiers de base et sauvegardes absents. Après vérification, choisissez <code>mode: &#39;apply&#39;</code> pour la création automatique. Autorisez <code>setObject</code> dans l’instance JavaScript et désactivez <strong>Do not subscribe to all states on start</strong>, car le script lit les caches d’états de manière synchrone. Une création propre au script interrompue peut être retentée après correction des autorisations ; les points étrangers ou modifiés restent protégés.</p><p>MQTT-Client <strong>0.1.24 ou ultérieur</strong> fournit le catalogue requis ; remplacer le fichier complet du script suffit pour cette correction. Les anciens topics persistants désélectionnés sans identité d’entité actuelle sont ignorés. Les métadonnées HA absentes ne sont jamais inventées. Le message de démarrage indique maintenant version et mode.</p><p>Le script regroupe les changements MQTT réels pendant une seconde. Le mode virtuel traite uniquement les sources concernées ; les répétitions identiques et les attributs sans rapport ne déclenchent aucun passage. Une analyse complète a lieu au démarrage et lorsque le catalogue de sélection ou la disponibilité change. La vérification du délai concerne uniquement les commandes en attente et cesse après confirmation ou expiration. Chaque entité utilise uniquement le canal de commande correspondant à son état ; les objets ioBroker existants ne sont pas supprimés.</p><h2 id="vis2" tabindex="-1">Nouveauté 0.1.24 : un point VIS 2 pour l’état et la commande <a class="header-anchor" href="#vis2" aria-label="Permalink to &quot;Nouveauté 0.1.24 : un point VIS 2 pour l’état et la commande {#vis2}&quot;">​</a></h2><p>Le script crée désormais automatiquement des points virtuels et dossiers sous <code>0_userdata.0.ugso_mqtt</code>. Il cible les API de l’adaptateur JavaScript ioBroker <strong>10.4.10</strong>. Commencez par <strong>mettre MQTT-Client à jour vers 0.1.24</strong> et reconnectez-le : le nouveau catalogue associe chaque entité à son topic actuel et à son autorisation de commande. Les anciens topics persistants ne doivent pas créer de commandes en double.</p><p>Conservez d’abord ces paramètres en haut du script complet :</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outputMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;virtual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mqttRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mqtt.0.ha_external&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualBackupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt_helper.backup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Après vérification de l’aperçu, passez à <code>mode: &#39;apply&#39;</code> et redémarrez. <strong>Le point de sauvegarde, les dossiers et les nouveaux points VIS 2 sont créés automatiquement.</strong> L’aperçu crée uniquement les dossiers de base et sauvegardes absents ; les nouveaux points VIS 2 nécessitent <code>apply</code>. Les points étrangers existants, alias et rôles manuels ne sont pas écrasés. Votre ancien alias, par exemple sous <code>alias.0.HA</code>, peut être conservé.</p><p>Exemple : <code>mqtt.0.ha_external.claudia_pc.switch.state</code> et son canal <code>mqtt.0.ha_external.claudia_pc.switch.set</code> deviennent <code>0_userdata.0.ugso_mqtt.claudia_pc.switch.state</code>. <strong>Utilisez uniquement ce point virtuel dans VIS 2.</strong></p><table tabindex="0"><thead><tr><th>Direction/fonction</th><th>Comportement</th></tr></thead><tbody><tr><td>Retour MQTT → VIS 2</td><td>État confirmé avec <code>ack: true</code></td></tr><tr><td>Action VIS 2 → commande MQTT</td><td>Seules les actions actuelles avec <code>ack: false</code> sont envoyées à <code>/set</code></td></tr><tr><td>Interrupteur</td><td>Normaliser virtuellement <code>on</code>/<code>off</code> en booléens ; renvoyer <code>ON</code>/<code>OFF</code></td></tr><tr><td>Luminosité</td><td>Pourcentage 0–100, limites vérifiées</td></tr><tr><td>RGB</td><td>Tableau JSON MQTT ↔ couleur hexadécimale virtuelle <code>#RRGGBB</code></td></tr><tr><td>Effet</td><td>Uniquement les choix de la liste d’effets actuelle</td></tr><tr><td>Température de couleur</td><td>Kelvin entiers dans les limites actuelles</td></tr><tr><td>Nombres, listes et texte</td><td>Vérifier les limites ou choix disponibles</td></tr><tr><td>Dates, mesures et batterie</td><td>Lecture seule ; valeurs MQTT d’origine conservées</td></tr></tbody></table><p>La création, le démarrage et le redémarrage n’envoient aucune commande et ne rejouent jamais d’anciennes actions. Un nouveau retour HA confirme la valeur ; l’acceptation par le broker ne confirme pas l’exécution. Sans nouveau retour pendant environ 30 secondes, la demande reste non confirmée avec la qualité d’erreur <code>q: 128</code>. Si la source est désélectionnée, inconnue ou hors ligne, la dernière valeur est conservée avec <code>q: 130</code> et les commandes sont bloquées. Aucune valeur zéro ou arrêt n’est inventée.</p><p>Le journal <code>virtualBackupId</code> est enregistré et vérifié avant chaque création. Il contient les associations et définitions d’objets, sans identifiants MQTT ni mesures actuelles. Le mode virtuel ne modifie pas les objets MQTT d’origine. Avec <code>mode: &#39;restore&#39;</code>, les valeurs virtuelles et références du tableau de bord sont conservées ; les commandes virtuelles propres au script passent en lecture seule et la synchronisation s’arrête. Arrêtez ensuite le script.</p><p>La fonction précédente reste accessible avec <code>outputMode: &#39;roles&#39;</code>. Les règles de rôles directs/alias et leur restauration ci-dessous concernent ce mode ; les tableaux décrivent aussi la signification des points virtuels. <strong>N’exécutez qu’une seule copie du script à la fois.</strong> Les attributs optionnels absents et le journal non encore créé ne produisent plus les anciens avertissements <code>getState</code>.</p><h2 id="installation" tabindex="-1">Installation et sauvegarde <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation et sauvegarde {#installation}&quot;">​</a></h2><ol><li>Exportez d’abord dans ioBroker Admin les objets MQTT concernés avec leurs états et les scripts existants, ou effectuez une sauvegarde complète.</li><li>Dans MQTT-Client, choisissez <strong>ioBroker-/VIS-2-Helfer herunterladen</strong>, ou <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/mqtt_client/app/iobroker/ugso-mqtt-role-mapper.js" target="_blank" rel="noreferrer">téléchargez le script</a>.</li><li>Dans <strong>Scripts</strong> d’ioBroker, créez un <strong>JavaScript</strong> et collez le fichier entier. Une seule copie doit fonctionner dans une seule instance JavaScript.</li><li>Réglez <code>mqttRoot</code> sur votre chemin MQTT, par exemple <code>mqtt.0.ha_external</code>. Les caractères génériques sont interdits.</li><li>Conservez <code>mode: &#39;preview&#39;</code>, démarrez le script et consultez son journal. L’aperçu crée uniquement les dossiers de base et sauvegardes absents.</li><li>Ajoutez dans <code>excludeIds</code> les points auxquels vous avez attribué manuellement le rôle générique <code>state</code>. Ce rôle manuel est indiscernable du rôle par défaut.</li><li>Après vérification, passez à <code>mode: &#39;apply&#39;</code> et redémarrez le script. Autorisez <code>setObject</code> dans les paramètres de l’instance JavaScript. Celle-ci doit pouvoir lire les états MQTT.</li></ol><p>Avant chaque modification, le rôle initial est enregistré dans l’état JSON <code>0_userdata.0.ugso_mqtt_roles.backup</code>, puis la sauvegarde est vérifiée. Le journal ne contient ni relevés de compteur ni identifiants de connexion. Un échec de sauvegarde bloque la modification suivante. Exportez également cet état de sauvegarde et conservez-le.</p><p>Les rôles spécifiques tels que <code>date</code>, <code>text</code> ou <code>value.temperature</code> ne sont pas remplacés. Une modification manuelle ultérieure empêche une nouvelle attribution automatique au même point. Aucun alias existant n’est écrasé.</p><h2 id="aliases" tabindex="-1">Rôles directs et alias en lecture seule <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Rôles directs et alias en lecture seule {#aliases}&quot;">​</a></h2><p>Les dates et horodatages reçoivent directement le rôle <code>date</code>. Le texte enregistré et les droits d’écriture sont conservés ; dans HA, <code>uptime</code> désigne la date de démarrage, pas une durée écoulée.</p><p>Dans ioBroker, les rôles de mesure et de capteur binaire sont en lecture seule. Si la source MQTT l’est déjà, seul son rôle générique est remplacé. Si elle est accessible en écriture, un alias en lecture seule est créé sous <code>alias.0.ugso_mqtt_roles</code> ; le rôle et les droits de l’original MQTT restent inchangés. Utilisez l’alias pour les visualisations et analyses. Ses valeurs proviennent toujours de l’état MQTT d’origine.</p><p>Le script vérifie les métadonnées et le type réel de la valeur. Il ne déduit pas les types des noms d’appareils ou des textes <code>on</code>/<code>off</code>. Les métadonnées absentes, unités incompatibles, dates invalides et classes inconnues sont ignorées. Il n’effectue aucune conversion et n’envoie aucune commande. Transmettez <code>device_class</code> et, pour les mesures, l’unité ; sélectionnez aussi ces attributs disponibles en mode manuel. La sélection par étiquette transmet automatiquement les métadonnées standard disponibles.</p><table tabindex="0"><thead><tr><th>Classe HA</th><th>Rôle ioBroker</th><th>Vérification</th></tr></thead><tbody><tr><td><code>date</code></td><td><code>date</code></td><td>Date <code>YYYY-MM-DD</code> valide</td></tr><tr><td><code>timestamp</code>, <code>uptime</code></td><td><code>date</code></td><td>Horodatage ISO avec fuseau horaire</td></tr></tbody></table><h2 id="numeric" tabindex="-1">Correspondances numériques appliquées <a class="header-anchor" href="#numeric" aria-label="Permalink to &quot;Correspondances numériques appliquées {#numeric}&quot;">​</a></h2><p>Le tableau indique les unités réellement acceptées. Les autres unités restent inchangées et sont ignorées ; les mA ou mV, par exemple, ne sont pas convertis implicitement.</p><table tabindex="0"><thead><tr><th>Classe HA</th><th>Rôle ioBroker</th><th>Unités acceptées</th></tr></thead><tbody><tr><td><code>temperature</code></td><td><code>value.temperature</code></td><td><code>°C</code>, <code>°F</code>, <code>K</code></td></tr><tr><td><code>humidity</code></td><td><code>value.humidity</code></td><td><code>%</code></td></tr><tr><td><code>absolute_humidity</code></td><td><code>value.humidity.absolute</code></td><td><code>g/m³</code>, <code>mg/m³</code></td></tr><tr><td><code>battery</code></td><td><code>value.battery</code></td><td><code>%</code></td></tr><tr><td><code>voltage</code></td><td><code>value.voltage</code></td><td><code>V</code></td></tr><tr><td><code>current</code></td><td><code>value.current</code></td><td><code>A</code></td></tr><tr><td><code>power</code></td><td><code>value.power</code></td><td><code>W</code>, <code>kW</code></td></tr><tr><td><code>energy</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>energy_storage</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>reactive_power</code></td><td><code>value.power.reactive</code></td><td><code>var</code>, <code>kvar</code>, <code>kVar</code></td></tr><tr><td><code>reactive_energy</code></td><td><code>value.energy.reactive</code></td><td><code>varh</code>, <code>kvarh</code>, <code>kVarh</code></td></tr><tr><td><code>frequency</code></td><td><code>value.frequency</code></td><td><code>Hz</code></td></tr><tr><td><code>pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>atmospheric_pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>illuminance</code></td><td><code>value.brightness</code></td><td><code>lx</code>, <code>lux</code></td></tr><tr><td><code>distance</code></td><td><code>value.distance</code></td><td><code>m</code>, <code>km</code>, <code>cm</code>, <code>mm</code>, <code>mi</code>, <code>nmi</code>, <code>yd</code>, <code>ft</code>, <code>in</code></td></tr><tr><td><code>duration</code></td><td><code>value.interval</code></td><td><code>s</code>, <code>ms</code>, <code>h</code>, <code>d</code></td></tr><tr><td><code>wind_speed</code></td><td><code>value.speed</code></td><td><code>m/s</code>, <code>km/h</code>, <code>mph</code>, <code>kn</code></td></tr><tr><td><code>volume_flow_rate</code></td><td><code>value.flow</code></td><td><code>m³/h</code></td></tr><tr><td><code>signal_strength</code></td><td><code>value.rssi</code></td><td><code>dBm</code></td></tr><tr><td><code>aqi</code></td><td><code>value.airquality</code></td><td>—</td></tr><tr><td><code>carbon_dioxide</code></td><td><code>value.co2</code></td><td><code>ppm</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>value.co</code></td><td><code>ppm</code></td></tr><tr><td><code>nitrogen_monoxide</code></td><td><code>value.no</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>nitrogen_dioxide</code></td><td><code>value.no2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>ozone</code></td><td><code>value.o3</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>sulphur_dioxide</code></td><td><code>value.so2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm1</code></td><td><code>value.pm1</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm25</code></td><td><code>value.pm25</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm10</code></td><td><code>value.pm10</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>radon</code></td><td><code>value.rn</code></td><td><code>Bq/m³</code></td></tr><tr><td><code>volatile_organic_compounds</code></td><td><code>value.tvoc</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>volatile_organic_compounds_parts</code></td><td><code>value.tvoc</code></td><td><code>ppb</code></td></tr></tbody></table><h2 id="binary" tabindex="-1">Capteurs binaires <a class="header-anchor" href="#binary" aria-label="Permalink to &quot;Capteurs binaires {#binary}&quot;">​</a></h2><p>Seules les véritables valeurs booléennes avec un type d’objet compatible sont acceptées. Les textes HA habituels <code>on</code> et <code>off</code> restent inchangés et ne reçoivent pas de rôle booléen. Pour <code>battery</code>, vrai signifie batterie faible ; pour <code>lock</code>, vrai signifie déverrouillé.</p><table tabindex="0"><thead><tr><th>Classe HA</th><th>Rôle ioBroker</th></tr></thead><tbody><tr><td><code>battery</code></td><td><code>indicator.lowbat</code></td></tr><tr><td><code>connectivity</code></td><td><code>indicator.reachable</code></td></tr><tr><td><code>door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>garage_door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>window</code></td><td><code>sensor.window</code></td></tr><tr><td><code>opening</code></td><td><code>sensor.contact</code></td></tr><tr><td><code>lock</code></td><td><code>sensor.lock</code></td></tr><tr><td><code>motion</code></td><td><code>sensor.motion</code></td></tr><tr><td><code>moisture</code></td><td><code>sensor.alarm.flood</code></td></tr><tr><td><code>smoke</code></td><td><code>sensor.alarm.fire</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>sensor.alarm.co</code></td></tr><tr><td><code>light</code></td><td><code>sensor.light</code></td></tr><tr><td><code>sound</code></td><td><code>sensor.noise</code></td></tr><tr><td><code>problem</code></td><td><code>indicator.error</code></td></tr><tr><td><code>running</code></td><td><code>indicator.working</code></td></tr></tbody></table><h2 id="conditional" tabindex="-1">Autres correspondances examinées <a class="header-anchor" href="#conditional" aria-label="Permalink to &quot;Autres correspondances examinées {#conditional}&quot;">​</a></h2><p>Le mode rôles seul n’applique pas ces cas automatiquement. Le mode virtuel réalise désormais les fonctions Light et interrupteur ci-dessous avec les vérifications indiquées ; les niveaux, consommation/production et classes ambiguës ne sont toujours pas devinés.</p><table tabindex="0"><thead><tr><th>Classe/fonction HA</th><th>Rôle possible</th><th>Condition supplémentaire</th></tr></thead><tbody><tr><td><code>volume_storage</code></td><td><code>value.fill</code></td><td>Confirmer un niveau réel de réservoir</td></tr><tr><td><code>water</code>, <code>gas</code></td><td>Mesure générique</td><td>Une consommation n’est pas un niveau</td></tr><tr><td><code>energy</code></td><td><code>value.energy.consumed</code> / <code>value.energy.produced</code></td><td>Identifier explicitement consommation ou production</td></tr><tr><td><code>speed</code></td><td><code>value.speed</code></td><td>Ne pas supposer qu’il s’agit du vent</td></tr><tr><td><code>moisture</code> numérique</td><td>Mesure générique</td><td>Distinguer d’une alarme d’eau binaire</td></tr><tr><td>Retour de luminosité</td><td><code>value.dimmer</code></td><td>Confirmer le pourcentage et la fonction Light</td></tr><tr><td>Commande de luminosité</td><td><code>level.dimmer</code></td><td>Raccorder correctement un canal de commande séparé</td></tr><tr><td>Retour d’interrupteur</td><td><code>sensor.switch</code></td><td>Normaliser une valeur booléenne</td></tr><tr><td>Commande d’interrupteur</td><td><code>switch</code> / <code>switch.light</code></td><td>Raccorder <code>/set</code> ; aucune commande à l’installation</td></tr><tr><td>Commande de température de couleur</td><td><code>level.color.temperature</code></td><td>Kelvin, limites et canal de commande</td></tr><tr><td>Sélection d’effet</td><td><code>level.effect</code></td><td>Liste d’effets et canal de commande</td></tr><tr><td>Commande RGB</td><td><code>level.color.rgb</code></td><td>Convertir le tableau JSON en couleur hexadécimale</td></tr></tbody></table><p>Aucun rôle spécifique n’est deviné pour <code>occupancy</code>, <code>presence</code>, <code>moving</code>, <code>plug</code>, <code>power</code> binaire, <code>battery_charging</code>, <code>cold</code>, <code>heat</code>, <code>gas</code> binaire, <code>glass_break</code>, <code>safety</code>, <code>tamper</code>, <code>update</code> ou <code>vibration</code>. Des rôles génériques <code>sensor</code>/<code>indicator</code> ou règles personnalisées sont possibles mais exclus de cette attribution automatique prudente. Toutes les autres classes non indiquées restent également inchangées.</p><h2 id="restore" tabindex="-1">Restauration <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restauration {#restore}&quot;">​</a></h2><p>Arrêtez le script, choisissez <code>mode: &#39;restore&#39;</code>, puis relancez-le. Seules ses propres modifications de rôle sont restaurées, si le rôle et le type actuels correspondent encore à l’entrée sauvegardée. Les modifications manuelles ultérieures sont conservées. Ses alias non modifiés sont supprimés ; les alias modifiés ou étrangers sont conservés. Les valeurs MQTT d’origine ne sont jamais supprimées.</p><p>Arrêtez ensuite le script. Conservez le journal et les exclusions. Les points déjà enregistrés ne sont pas traités de nouveau avec le même journal ; une nouvelle opération exige un nouveau <code>backupId</code> choisi délibérément et, pour les alias, un <code>aliasRoot</code> libre.</p><p>Vérification locale avec des API ioBroker simulées : aperçu, échecs de sauvegarde, types, unités, modifications manuelles, alias et restauration. Pas encore testé dans une installation ioBroker réelle.</p><p><a href="https://www.home-assistant.io/integrations/sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Sensor</a> · <a href="https://www.home-assistant.io/integrations/binary_sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Binary sensor</a> · <a href="https://www.iobroker.com/docs/dev/stateroles.md" target="_blank" rel="noreferrer">ioBroker: State roles</a> · <a href="https://github.com/ioBroker/ioBroker.javascript/blob/v10.4.10/docs/en/javascript.md" target="_blank" rel="noreferrer">ioBroker: JavaScript API</a></p>`,43)])])}const h=t(a,[["render",r]]);export{m as __pageData,h as default};
